#include <stdlib.h>
#include <stdio.h>

int main() {
    int *leakyPointer = (int *)malloc(sizeof(int)); // Allocate memory for an integer

    if (leakyPointer == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return 1;
    }

    *leakyPointer = 42; // Assign a value to the allocated memory

    printf("Value: %d\n", *leakyPointer);

    free(leakyPointer); // Free the allocated memory

    return 0;
}
